GRAMMAR = {
    "A1": ["sentence", "nouns", "verbs", "food"],
    "A2": ["way", "shop"],
    "B1": ["plan", "if"],
    "B2": ["reason", "choice"],
}


def lesson(level, n, title, place, aim, words, lines):
    return {
        "id": f"{level.lower()}-{n:02d}",
        "level": level,
        "n": n,
        "title": title,
        "place": place,
        "aim": aim,
        "words": words,
        "lines": [{"who": who, "en": text} for who, text in lines],
        "image": IMG[place],
        "grammar": GRAMMAR[level][(n - 1) % len(GRAMMAR[level])],
    }


def pack(level, rows):
    assert len(rows) == 50, (level, len(rows))
    return [lesson(level, i + 1, *row) for i, row in enumerate(rows)]


