def main():
    lessons = pack("A1", A1) + pack("A2", A2) + pack("B1", B1) + pack("B2", B2)
    scenes = []
    for index, item in enumerate(TALK, start=1):
        prefix = f"u{index:02d}"
        turns = []
        for n, line in enumerate(item["lines"]):
            turns.append({
                "id": f"{prefix}-{n}",
                "speaker": "Anna" if n % 2 == 0 else "Marko",
                "en": line,
            })
        scenes.append({
            "id": f"use-{index:02d}",
            "domain": item["domain"],
            "level": item["level"],
            "title": item["title"],
            "aim": item["aim"],
            "scene": item["scene"],
            "image": item["image"],
            "turns": turns,
        })
    out_l = ROOT / "src/data/path-lessons.json"
    out_t = ROOT / "src/data/talk-more.json"
    out_l.write_text(json.dumps(lessons, ensure_ascii=False, indent=2) + "\n")
    out_t.write_text(json.dumps(scenes, ensure_ascii=False, indent=2) + "\n")
    print(len(lessons), len(scenes), out_l, out_t)


if __name__ == "__main__":
    main()
